'use strict';const assert=require('node:assert/strict');
module.exports=async({variant,run,wait,check,tap,submit,issue,until,sleep,requests,checks,findings,setMode})=>{
 const after=variant==='after';
 await check('sandbox has no Node or real native bridge','({node:typeof require,process:typeof process,native:typeof HarnessMobileControl.inputAction})',{node:'undefined',process:'undefined',native:'undefined'});
 await check('actual Controller scopeOf matches exact Gateway target','ctx.sessions.scopeOf(scopes.get("synthetic-a"))','synthetic-a');
 const normal=issue('touch-normal');await submit(normal);await until(()=>normal.settlements.length===1,'normal controlled receipt');assert.deepEqual(normal.settlements[0].value.answers[0].selected,['Option 0']);await wait('!state().pending');checks.push({name:'trusted DOM touch actual RPC/server parser',receipt:normal.settlements[0]});
 setMode('normal',350);const held=issue('same-tick-delayed');await submit(held,{sameTick:true});await until(()=>requests.length===2,'held result port');await check(after?'card retained while complete HTTP response withheld':'before: card already removed while response withheld','Boolean(state().pending)',after);if(after){await check('held busy fieldset','state().fieldsetDisabled',true);await check('held state submitting','state().phase','submitting')}
 assert.equal(held.settlements.length,0);await until(()=>held.settlements.length===1,'held receipt');await wait('!state().pending');assert.deepEqual(held.settlements[0].value.answers[0].selected,['Option 0','Option 1']);assert.equal(requests.length,2);checks.push({name:'same-tick extra selection + double-submit retains both, one RPC',receipt:held.settlements[0]});
 setMode('reject-before');const retry=issue('draft-recovery');await wait('pendingBySession.get(activeSession)?.questions[0].id==="draft-recovery"');const key=await run('state().pending');await submit(retry);await until(()=>requests.length===3&&requests[2].done,'consumed body 503');setMode('normal');await wait(`state().pending&&state().pending!==${JSON.stringify(key)}`);await check(after?'503 real fresh generation restores draft':'before: 503 fresh generation loses draft','state().checked',after?['true','false','false']:['false','false','false']);assert.equal(retry.settlements.length,0);await sleep(120);assert.equal(requests.length,3,'no automatic business retransmission');if(after){await check('authentic re-presentation recovery notice','state().status.includes("已保留选择")',true);await tap('.Mbwy4a_footerActions > :last-child')}else await submit(retry);await until(()=>retry.settlements.length===1,'explicit retry receipt');await wait('!state().pending');assert.equal(requests.length,4);checks.push({name:'only explicit submit sends restored/new selection',receipt:retry.settlements[0]});
 if(after)await check('ACK removes cache and timers','registry.stats()',{entries:0,views:0,bytes:0,timers:0});
 findings.push({variant,comparison:'350ms response hold plus consumed-body503; local controlled source outcome only; no business winner inference or WAN claim'});
};
